#include "function_logging_support.h"
#include "function_logging_production.h"

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <new>
#include <stdexcept>

static bool countAllocations = false;
static std::size_t allocations = 0;
static std::size_t allocatedBytes = 0;
static volatile std::size_t observedCalls = 0;

void* operator new(std::size_t size) {
  if (countAllocations) {
    ++allocations;
    allocatedBytes += size;
  }
  if (void* pointer = std::malloc(size ? size : 1)) {
    return pointer;
  }
  throw std::bad_alloc();
}
void* operator new[](std::size_t size) { return ::operator new(size); }
void operator delete(void* pointer) noexcept { std::free(pointer); }
void operator delete[](void* pointer) noexcept { std::free(pointer); }
void operator delete(void* pointer, std::size_t) noexcept { std::free(pointer); }
void operator delete[](void* pointer, std::size_t) noexcept { std::free(pointer); }

static void require(bool condition, const char* message) {
  if (!condition) {
    throw std::runtime_error(message);
  }
}

struct LongNamedClientD3D9LoggingProbe {
  void representativeHighFrequencyApiCall() {
    LogFunctionCall();
    ++observedCalls;
  }
  const char* earlyReturnFromHighFrequencyApiCall() {
    LogFunctionCall();
    return __FUNCTION__;
  }
  void exceptionFromHighFrequencyApiCall() {
    LogFunctionCall();
    throw 17;
  }
};

static const char* representativeStaticD3D9ApiCall() {
  LogStaticFunctionCall();
  ++observedCalls;
  return __FUNCTION__;
}

static void configure(bool api, bool all) {
  GlobalOptions::logApiCalls = api;
  GlobalOptions::logAllCalls = all;
  capturedLogs.clear();
}

static void expectLog(std::size_t index, const std::string& name, void* object) {
  require(index < capturedLogs.size(), "Missing log entry");
  require(capturedLogs[index].name == name, "Log content changed");
  require(capturedLogs[index].object == object, "Log object pointer changed");
}

static void verifyLoggingSemantics() {
  LongNamedClientD3D9LoggingProbe probe;
  for (bool api : {false, true}) {
    for (bool all : {false, true}) {
      configure(api, all);
      {
        FunctionEntryExitLogger outer("Direct3DDevice9_LSS::DrawIndexedPrimitive", &probe);
        {
          FunctionEntryExitLogger inner("Direct3DVertexBuffer9_LSS::Unlock", nullptr);
        }
      }
      if (all) {
        require(capturedLogs.size() == 4, "All-call nesting lost entry/exit events");
        expectLog(0, "Direct3DDevice9_LSS::DrawIndexedPrimitive ENTRY", &probe);
        expectLog(1, "\tDirect3DVertexBuffer9_LSS::Unlock ENTRY", nullptr);
        expectLog(2, "\tDirect3DVertexBuffer9_LSS::Unlock EXIT", nullptr);
        expectLog(3, "Direct3DDevice9_LSS::DrawIndexedPrimitive EXIT", &probe);
      } else if (api) {
        require(capturedLogs.size() == 1, "API mode must log only the outer call");
        expectLog(0, "Direct3DDevice9_LSS::DrawIndexedPrimitive", &probe);
      } else {
        require(capturedLogs.empty(), "Disabled logging emitted an event");
      }
    }
  }

  configure(false, true);
  const char* returnedName = probe.earlyReturnFromHighFrequencyApiCall();
  require(capturedLogs.size() == 2, "Early return lost RAII exit");
  expectLog(0, std::string(returnedName) + " ENTRY", &probe);
  expectLog(1, std::string(returnedName) + " EXIT", &probe);
  capturedLogs.clear();
  try {
    probe.exceptionFromHighFrequencyApiCall();
  } catch (int value) {
    require(value == 17, "Exception was changed");
  }
  require(capturedLogs.size() == 2, "Exception unwinding lost RAII exit");
  std::string exceptionName = capturedLogs[0].name;
  require(exceptionName.find("exceptionFromHighFrequencyApiCall") != std::string::npos,
    "Production macro lost the function name");
  exceptionName.resize(exceptionName.size() - std::strlen(" ENTRY"));
  expectLog(1, exceptionName + " EXIT", &probe);

  capturedLogs.clear();
  const char* staticName = representativeStaticD3D9ApiCall();
  require(capturedLogs.size() == 2, "Static macro lost entry/exit");
  expectLog(0, std::string(staticName) + " ENTRY", nullptr);
  expectLog(1, std::string(staticName) + " EXIT", nullptr);

  configure(false, true);
  {
    char mutableName[] = "Direct3DDevice9_LSS::OriginalFunctionName";
    FunctionEntryExitLogger logger(mutableName, &probe);
    mutableName[0] = 'X';
  }
  require(capturedLogs.size() == 2, "Owned-name test lost entry/exit");
  expectLog(0, "Direct3DDevice9_LSS::OriginalFunctionName ENTRY", &probe);
  expectLog(1, "Direct3DDevice9_LSS::OriginalFunctionName EXIT", &probe);

  // An unindented subsequent event proves all previous scopes balanced depth.
  capturedLogs.clear();
  {
    FunctionEntryExitLogger logger("DepthAfterAllScopes", nullptr);
  }
  expectLog(0, "DepthAfterAllScopes ENTRY", nullptr);
  expectLog(1, "DepthAfterAllScopes EXIT", nullptr);
  configure(false, false);
}

static void verifyDisabledAllocations() {
  LongNamedClientD3D9LoggingProbe probe;
  configure(false, false);
  allocations = 0;
  allocatedBytes = 0;
  countAllocations = true;
  for (std::size_t index = 0; index < 10000; ++index) {
    probe.representativeHighFrequencyApiCall();
    representativeStaticD3D9ApiCall();
  }
  countAllocations = false;
  std::printf("Disabled logger: %zu allocations, %zu bytes for 20000 calls\n", allocations, allocatedBytes);
  require(capturedLogs.empty(), "Disabled logging emitted an event");
  require(allocations == 0, "Disabled logger allocated for function names");
}

static void benchmark(std::size_t iterations) {
  LongNamedClientD3D9LoggingProbe probe;
  configure(false, false);
  for (std::size_t index = 0; index < 25000; ++index) {
    probe.representativeHighFrequencyApiCall();
  }
  allocations = 0;
  allocatedBytes = 0;
  countAllocations = false;
  const auto begin = std::chrono::steady_clock::now();
  for (std::size_t index = 0; index < iterations; ++index) {
    probe.representativeHighFrequencyApiCall();
  }
  const auto end = std::chrono::steady_clock::now();
  // Count separately so old allocating calls do not pay the instrumentation
  // increments in the timed loop. Both variants use the same operator new.
  countAllocations = true;
  for (std::size_t index = 0; index < iterations; ++index) {
    probe.representativeHighFrequencyApiCall();
  }
  countAllocations = false;
  const double elapsedNs = std::chrono::duration<double, std::nano>(end - begin).count();
  std::printf("{\"iterations\":%zu,\"elapsed_ns\":%.0f,\"ns_per_call\":%.6f,\"allocations\":%zu,\"allocated_bytes\":%zu}\n",
    iterations, elapsedNs, elapsedNs / static_cast<double>(iterations), allocations, allocatedBytes);
}

int main(int argc, char** argv) {
  try {
    if (argc == 3 && std::strcmp(argv[1], "--benchmark") == 0) {
      const auto iterations = static_cast<std::size_t>(std::strtoull(argv[2], nullptr, 10));
      require(iterations >= 10000 && iterations <= 50000000, "Invalid iteration count");
      benchmark(iterations);
    } else if (argc == 2 && std::strcmp(argv[1], "--semantics-only") == 0) {
      verifyLoggingSemantics();
      std::puts("Production function logging semantics passed");
    } else {
      // Verify the first disabled call before any logging depth is allocated.
      verifyDisabledAllocations();
      verifyLoggingSemantics();
      verifyDisabledAllocations();
      std::puts("Production function logging regression passed");
    }
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "%s\n", error.what());
    return 1;
  }
}
